from second_canada_author import *

def refpage(p,pg,n): return dict(page=pg,paragraph=n,quote=p[pg-1].strip())
def eventpage(p,pg,n,date,summary,labels=()):
    return dict(page=pg,paragraph=n,quote=p[pg-1].strip(),date=date,event=summary,labels=list(labels),date_precision='unknown' if not date else {4:'year',7:'month',10:'day'}[len(date)])
def base(rid,sh,name,date,bp):
    return dict(record_id=rid,source=sh,jurisdiction='bc',court='Commission of Inquiry into Money Laundering in British Columbia',court_file=None,family='ca/bc/cullen-inquiry',proceeding='Commission of Inquiry into Money Laundering in British Columbia',subject='institutional governance, professional regulation and financial compliance',deponent=name,sworn_date=date,body_pages=list(range(1,bp+1)),exhibits=[],events=[],discrepancies=[],difficulty=[],distractors=[])
def attach(s,p,l,a,b,pg,n,d,k='report',cover=()):
    s['exhibits'].append(dict(label=l,pages=list(range(a,b+1)),cover_pages=list(cover),description=d,kind=k,references=[refpage(p,pg,n)]))
